package edu.asu.diging.vspace.core.model;


public interface IVSFile extends IVSMedia {
    
    String getFilename();

    void setFilename(String filename);

    void setFileType(String fileType);

    String getFileType();

    String getOriginalFileName();

    void setOriginalFileName(String originalFileName);

    String getFileDescription();

    void setFileDescription(String fileDescription);

    /**
     * Name of the file on disk. This is generated by the server and is
     * independent of the display name returned by {@link #getFilename()}.
     * Files uploaded before this field existed have no stored name and
     * are kept on disk under their display name.
     */
    String getStoredFileName();

    void setStoredFileName(String storedFileName);

}
